import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, BoxGeometry, Color, PointLight, AmbientLight, DoubleSide } from 'three/webgpu';
import { uniform, time, vec3, mix, smoothstep, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group, Mesh, PlaneGeometry, BoxGeometry,
    Color, PointLight, AmbientLight, DoubleSide,
  } = THREE;

  const group = new Group();
  group.name = 'home-stat-tile';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  // ---- Stage / backdrop plate (dark, never void) ----
  const stageW = 7, stageH = 6;
  const stageUniforms = {
    top: uniform(vec3(surface).rgb.smul(1.4)),
    bottom: uniform(vec3(ink).rgb),
  };
  const stageMat = new MeshStandardNodeMaterial({
    roughness: 0.85,
    metalness: 0.18,
    side: DoubleSide,
  });
  const v = uv();
  stageMat.colorNode = mix(stageUniforms.bottom, stageUniforms.top, smoothstep(0.0, 1.0, v.y));
  const stage = new Mesh(new PlaneGeometry(stageW, stageH), stageMat);
  stage.position.set(0, 0, -2.5);
  stage.name = 'stat-tile-stage';
  group.add(stage);

  // ---- Card container that lifts on hover ----
  const card = new Group();
  card.name = 'stat-card';
  group.add(card);

  // ---- Load GLB machined-metal mesh ----
  const glbUrl = config.meshUrl;
  let glbRoot = null;
  let glbMeshes = [];
  if (glbUrl) {
    ctx.glbLoader.loadGLB(glbUrl).then((gltf) => {
      glbRoot = gltf.scene;
      glbRoot.traverse((o) => {
        if (o.isMesh) {
          glbMeshes.push(o);
          // machined-metal PBR discipline: roughness>=0.5, metalness<=0.55
          const mats = Array.isArray(o.material) ? o.material : [o.material];
          mats.forEach((m) => {
            if (m && 'roughness' in m) m.roughness = Math.max(m.roughness ?? 1, 0.5);
            if (m && 'metalness' in m) m.metalness = Math.min(m.metalness ?? 0, 0.55);
            if (m && 'clearcoat' in m) m.clearcoat = Math.min(m.clearcoat ?? 0, 0.25);
            if (m && m.color) m.color = m.color.clone().lerp(paper, 0.35);
          });
        }
      });
      card.add(glbRoot);
      // soft weighted-settle entrance
      const settleState = { s: 0.94 };
      gsap.to(settleState, {
        s: 1.0, duration: 0.9, ease: 'power4.out', overwrite: true,
        onUpdate: () => { card.scale.setScalar(settleState.s); },
      });
      gsap.from(card.position, { y: 0.4, duration: 0.7, ease: 'power3.out', overwrite: true });
      gsap.from(card.rotation, { x: -0.12, duration: 0.8, ease: 'power2.out', overwrite: true });
    });
  }

  // ---- Accent edge bar (signal red, the ONE brightest accent) ----
  const edgeLen = 0.78;
  const edgeBar = new Mesh(
    new BoxGeometry(edgeLen, 0.018, 0.018),
    new MeshStandardNodeMaterial({
      color: accent,
      emissive: accent,
      emissiveIntensity: 0.0,
      roughness: 0.45,
      metalness: 0.4,
    })
  );
  edgeBar.position.set(0, 0.32, 0.05);
  edgeBar.name = 'accent-edge';
  card.add(edgeBar);

  // accent edge fade-in
  gsap.to(edgeBar.material, { emissiveIntensity: 0.9, duration: 0.6, ease: 'power2.out', delay: 0.4 });

  // ---- Contact shadow plane under the card ----
  const shadowUniforms = { opacity: uniform(0.55) };
  const shadowMat = new MeshStandardNodeMaterial({
    transparent: true,
    roughness: 1.0,
    metalness: 0.0,
  });
  const su = uv();
  const r = su.sub(vec3(0.5, 0.5, 0.0)).length();
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = shadowUniforms.opacity.mul(smoothstep(0.5, 0.05, r));
  const shadowPlane = new Mesh(new THREE.CircleGeometry(1.4, 48), shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.set(0, -0.42, 0.0);
  shadowPlane.name = 'contact-shadow';
  card.add(shadowPlane);

  // ---- Lights (node-local): key is scene-provided; add rim + accent ----
  const rim = new PointLight(accent, 0.8, 6.0, 1.8);
  rim.position.set(-1.2, 0.6, -1.2);
  rim.name = 'stat-rim';
  card.add(rim);

  const back = new PointLight(0xffffff, 0.5, 6.0, 1.5);
  back.position.set(0.8, -0.4, -1.6);
  card.add(back);

  const fill = new AmbientLight(0x222230, 0.4);
  card.add(fill);

  // ---- Cinematic primitive: parallax-scroll (scroll trigger) ----
  const primitiveResults = [];
  (config.cinematicPrimitives ?? []).forEach((p) => {
    if (ctx.primitives && typeof ctx.primitives[p.name] === 'function') {
      const r = ctx.primitives[p.name](group, p.params ?? {});
      if (r) primitiveResults.push(r);
    }
  });

  // ---- Interaction state ----
  const state = { hovered: false, pressed: false, baseY: 0 };
  const tlHover = gsap.timeline({ paused: true });
  tlHover.to(card.position, { y: state.baseY + 0.15, duration: 0.55, ease: 'power3.out' }, 0);
  tlHover.to(edgeBar.material, { emissiveIntensity: 1.6, duration: 0.4, ease: 'power2.out' }, 0);
  tlHover.to(card.rotation, { x: -0.05, y: 0.05, duration: 0.5, ease: 'power2.out' }, 0);

  function onEnter() {
    state.hovered = true;
    tlHover.play();
  }
  function onLeave() {
    state.hovered = false;
    tlHover.reverse();
  }
  function onDown() {
    state.pressed = true;
    gsap.to(card.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)', overwrite: true });
  }
  function onUp() {
    state.pressed = false;
    gsap.to(card.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.4, ease: 'power3.out', overwrite: true });
  }
  function onClick() {
    ctx.emit('hub-home.select', { node: 'home-stat-tile' });
  }

  group.userData.handlers = {
    pointermove: () => {},
    pointerenter: onEnter,
    pointerleave: onLeave,
    pointerdown: onDown,
    pointerup: () => { onUp(); onClick(); },
    click: onClick,
  };

  // ---- Cleanup ----
  let disposed = false;
  group.userData.cleanup = function cleanup() {
    if (disposed) return; disposed = true;
    tlHover.kill();
    gsap.killTweensOf(card.position);
    gsap.killTweensOf(card.rotation);
    gsap.killTweensOf(card.scale);
    gsap.killTweensOf(edgeBar.material);
    primitiveResults.forEach((r) => { try { r.cleanup && r.cleanup(); } catch (e) {} });
    primitiveResults.length = 0;
    [edgeBar.material, shadowMat, stageMat].forEach((m) => {
      try { m.disposeNode && m.disposeNode(); } catch (e) {}
      try { m.dispose && m.dispose(); } catch (e) {}
    });
    [edgeBar, shadowPlane, stage].forEach((o) => { try { o.geometry && o.geometry.dispose(); } catch (e) {} });
    glbMeshes.length = 0;
    glbRoot = null;
  };

  return group;
}
